import{_ as o,o as a,c as t,a2 as c}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"内容搜索","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/content-search.md","filePath":"zh-CN/user-guide/content-search.md","lastUpdated":1788190459000}'),r={name:"zh-CN/user-guide/content-search.md"};function d(s,e,n,l,i,h){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="内容搜索" tabindex="-1">内容搜索 <a class="header-anchor" href="#内容搜索" aria-label="Permalink to &quot;内容搜索&quot;">​</a></h1><p>内容搜索插件可以检索本地文档中的正文，并在后台建立索引，与 Lertaro 原有的文件名搜索并行工作。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>打开<strong>设置 → 插件 → 内容搜索 → 配置</strong>，至少设置一个监测文件夹并保存。默认触发关键字为 <code>cs</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cs 项目计划</span></span></code></pre></div><p>关键字后必须跟一个空格。如果 <code>cs</code> 与你的使用习惯冲突，可以在插件设置中改成其他关键字。</p><h2 id="索引内容" tabindex="-1">索引内容 <a class="header-anchor" href="#索引内容" aria-label="Permalink to &quot;索引内容&quot;">​</a></h2><ul><li><strong>监测文件夹</strong>：插件会递归扫描配置的本地文件夹，并支持 <code>%USERPROFILE%</code> 等环境变量。</li><li><strong>文件后缀</strong>：默认包含 <code>txt</code>、<code>md</code>、<code>pdf</code>、<code>docx</code>、<code>docm</code>、<code>pptx</code>、<code>pptm</code>、<code>xlsx</code>、<code>xlsm</code> 和 <code>csv</code>，你可以按需要修改逗号分隔的列表。</li><li><strong>PDF 文件</strong>：会同时检索可提取的页面正文和已保存的可填写 PDF 表单字段值。</li><li><strong>文件大小</strong>：超过单个文件大小上限的文件会被跳过；内容索引还有独立的体积上限，设为 <code>0</code> 表示不限制。</li><li><strong>排除路径</strong>：输入以分号分隔的正则表达式来排除匹配的完整路径。文件夹路径匹配时，其内容也会被排除。</li></ul><p>只有成功提取出正文的文件才会参与搜索。没有对应文档提取器的二进制文件会被跳过，不会作为乱码文本写入索引。</p><h2 id="搜索方式" tabindex="-1">搜索方式 <a class="header-anchor" href="#搜索方式" aria-label="Permalink to &quot;搜索方式&quot;">​</a></h2><p>在快速搜索窗口中输入 <code>cs</code>、空格和关键词即可搜索。结果会显示匹配文件的正文片段及所在文件夹，按下 <code>Enter</code> 可打开选中的文件。查询有结果时，在未选择类型筛选的情况下，完整搜索窗口中也会显示这些文件结果。</p><p>首次建立索引时，<code>cs</code> 占位结果会显示已索引文件数和剩余任务数。新文件和发生变化的文件会在后台处理，索引期间不会影响普通文件名搜索。</p><h2 id="清空与重建" tabindex="-1">清空与重建 <a class="header-anchor" href="#清空与重建" aria-label="Permalink to &quot;清空与重建&quot;">​</a></h2><p>内容搜索设置中提供两个不同的操作：</p><ul><li><strong>清空索引</strong>：删除内容索引，但不会重新扫描监测文件夹。</li><li><strong>重建索引</strong>：删除内容索引，然后重新扫描所有监测文件夹。</li></ul><p>这两个操作只影响内容搜索索引，不会删除 Lertaro 的普通文件名索引。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to &quot;使用提示&quot;">​</a></h2><ul><li>如果文件没有出现在结果中，请检查它所在的文件夹、后缀、排除规则和大小上限。</li><li>修改监测文件夹或索引规则后，请保存设置并等待后台扫描完成。</li><li>修改规则后如果希望重新提取已有文件，请使用<strong>重建索引</strong>。</li></ul>',18)])])}const g=o(r,[["render",d]]);export{u as __pageData,g as default};
